export type ExporterState = "healthy" | "degraded" | "wedged";

export interface ExporterHealth {
  state: ExporterState;
  queueDepth: number;
  lastSuccessAgeMs: number | null;
  detail: string;
}

/** Past this many queued batches the exporter is not keeping up, whatever the clock says. */
const DEGRADED_QUEUE_DEPTH = 8;
/** No successful export in this long means the collector is not answering at all. */
const WEDGED_SILENCE_MS = 120_000;

/**
 * Classify the exporter from the two facts it already knows.
 *
 * A null `lastSuccessAgeMs` means it has never succeeded, which is `wedged` rather than
 * `healthy`: a process that has not managed one export is the case this probe exists to
 * catch, and defaulting it to healthy would hide exactly the startup misconfiguration an
 * operator most needs to see.
 */
export function exporterHealth(
  queueDepth: number,
  lastSuccessAgeMs: number | null,
): ExporterHealth {
  if (lastSuccessAgeMs === null) {
    return { state: "wedged", queueDepth, lastSuccessAgeMs, detail: "no export has ever succeeded" };
  }
  if (lastSuccessAgeMs >= WEDGED_SILENCE_MS) {
    return {
      state: "wedged",
      queueDepth,
      lastSuccessAgeMs,
      detail: `no export in ${Math.round(lastSuccessAgeMs / 1000)}s`,
    };
  }
  if (queueDepth >= DEGRADED_QUEUE_DEPTH) {
    return { state: "degraded", queueDepth, lastSuccessAgeMs, detail: `${queueDepth} batches queued` };
  }
  return { state: "healthy", queueDepth, lastSuccessAgeMs, detail: "keeping up" };
}

import { type ExporterHealth } from "./exporter-health.ts";

export interface FleetCounts {
  active: number;
  waiting: number;
  idle: number;
}

/**
 * A one-line summary of the fleet's current state.
 *
 * A healthy exporter adds nothing: the summary is read constantly, and a permanent "telemetry
 * healthy" suffix would train the eye to skip the end of the line - which is where the
 * unhealthy case has to be noticed.
 */
export function summarize(counts: FleetCounts, exporter?: ExporterHealth): string {
  const base = `${counts.active} active, ${counts.waiting} waiting, ${counts.idle} idle`;
  if (!exporter || exporter.state === "healthy") return base;
  return `${base} - telemetry ${exporter.state} (${exporter.detail})`;
}

import assert from "node:assert/strict";
import test from "node:test";
import { exporterHealth } from "./exporter-health.ts";

test("a shallow queue with a recent success is healthy", () => {
  assert.equal(exporterHealth(1, 2_000).state, "healthy");
});

test("a deep queue is degraded even when exports are landing", () => {
  const health = exporterHealth(12, 2_000);
  assert.equal(health.state, "degraded");
  assert.match(health.detail, /12 batches queued/);
});

test("a long silence is wedged whatever the queue looks like", () => {
  assert.equal(exporterHealth(0, 300_000).state, "wedged");
});

test("never having succeeded is wedged, not healthy", () => {
  const health = exporterHealth(0, null);
  assert.equal(health.state, "wedged");
  assert.match(health.detail, /never succeeded/);
});
